const youGet = require('./engines/you-get');
const wget = require('./engines/wget');
const bilili = require('./engines/bilili');
const youtubeDl = require('./engines/youtube-dl');
const ytDLP = require('./engines/yt-dlp')
const list = [];
const logger = require('./logger');

const run = () => {
    const callback = (error, stderr) => {
        if (error) {
            logger.error(`Download error: ${JSON.stringify(list[0], null, 4)}, ${stderr}`);
        } else {
            logger.info(`Download success: ${JSON.stringify(list[0], null, 4)}`);
        }
        list.splice(0, 1);
        if (list.length) {
            run();
        }
    }
    switch (list[0].engine) {
        case 'you-get':
            youGet(list[0], callback);
            break;
        case 'wget':
            wget(list[0], callback);
            break;
        case 'bilili':
            bilili(list[0], callback);
            break;
        case 'youtube-dl':
            youtubeDl(list[0], callback);
            break;
        case 'yt-dlp':
            ytDLP(list[0], callback)
    }
}

module.exports = (options, result) => {
    list.push(options);
    if (list.length === 1) {
        run();
    }
}

const Koa = require('koa');
const bodyParser = require('koa-bodyparser');
const downloader = require('./downloader');
const config = require('./config');
const logger = require('./logger');
const { exec } = require('child_process');
exec(`mkdir downloads`);

const app = new Koa();
app.use(bodyParser());

app.use(ctx => {
    const options = Object.assign({
        'engine': 'you-get',
        'path': '',
        'url': '',
        'name': '',
        'playlist': '0',
        'list': '',
    }, ctx.request.body);

    const result = {
        code: 0,
        data: options,
    }

    if (config.secret && config.secret !== options.secret) {
        result.code = 1;
        result.msg = 'wrong secret';
    } else if (!options.url) {
        result.code = 2;
        result.msg = 'lacking url';
    } else if (['you-get', 'wget', 'bilili', 'youtube-dl', 'yt-dlp'].indexOf(options.engine) === -1) {
        result.code = 3;
        result.msg = 'unsupported engine';
    } else {
        if (options.list && options.engine === 'wget') {
            const list = JSON.parse(options.list);
            list.forEach((item) => {
                const newOptions = JSON.parse(JSON.stringify(options));
                newOptions.url = item;
                newOptions.name = newOptions.name + '-' + item.replace(/\?.*/, '').match(/(.+)(\/)(.*)/)[3];
                downloader(newOptions, result);
            });
        } else {
            downloader(options, result);
        }
    }

    ctx.body = JSON.stringify(result);
});

app.listen(config.port);

const winston = require('winston');
const config = require('./config');
const Transport = require('winston-transport');
const got = require('got');

class HTTPTransport extends Transport {
    constructor(opts) {
        super(opts);
    }

    async log (info, callback) {
        if (config.telegram_chat_id && config.telegram_token) {
            got({
                method: 'post',
                url: `https://api.telegram.org/bot${config.telegram_token}/sendMessage`,
                json: {
                    chat_id: config.telegram_chat_id,
                    text: info.message,
                },
            });
        }
        if (config.ftqq_sckey) {
            got({
                method: 'post',
                url: `https://sc.ftqq.com/${config.ftqq_sckey}.send`,
                form: {
                    text: info.message.split(': ')[0],
                    desp: info.message,
                },
            });
        }
        callback();
    }
};

const logger = winston.createLogger({
    level: 'info',
    format: winston.format.json(),
    transports: [
        new winston.transports.File({
            filename: 'logs/error.log',
            level: 'error',
        }),
        new winston.transports.File({ filename: 'logs/combined.log' }),
        new winston.transports.Console({
            format: winston.format.combine(winston.format.colorize(), winston.format.simple()),
            silent: process.env.NODE_ENV === 'test',
        }),
        new HTTPTransport({
            silent: process.env.NODE_ENV === 'test',
        }),
    ],
});

module.exports = logger;

const dotenv = require('dotenv');
dotenv.config();

module.exports = {
    port: process.env.PORT || 3000,
    retryTimes: process.env.RETRY_TIMES || 3,
    secret: [REDACTED],
    bilibili_cookie_path: process.env.BILIBILI_COOKIE_PATH,
    sessdata: process.env.BILIBILI_SESSDATA,
    telegram_token: [REDACTED],
    telegram_chat_id: process.env.TELEGRAM_CHAT_ID,
    ftqq_sckey: process.env.FTQQ_SCKEY,
    command_prefix: process.env.COMMAND_PREFIX,
};

const { exec } = require('child_process');
const config = require('../config');
const { download } = require('./utils');

module.exports = (options, callback) => {
    let op = '-y --playlist-type=no';
    let path = '';
    if (options.path) {
        path = `downloads/${options.path}`;
        exec(`mkdir -p ${path}`);
    }
    else {
        path = `downloads`;
    }
    op += ` -d ${path}`;
    if (options.sessdata || config.sessdata) {
        op += ` -c ${options.sessdata || config.sessdata}`;
    }

    download(`bilili ${op} '${options.url}' >> logs/bilili.log`, callback);
}

const { download } = require('./utils');

module.exports = (options, callback) => {
    let op = `--all-subs --no-check-certificate`;
    let path = '';
    if (options.path) {
        path = `downloads/${options.path}/%(title)s-%(id)s.%(ext)s`;
    }
    else {
        path = `downloads/%(title)s-%(id)s.%(ext)s`;
    }
    op += ` -o '${path}'`;

    download(`youtube-dl ${op} '${options.url}' >> logs/youtube-dl.log`, callback);
}

const { exec } = require('child_process');
const { download } = require('./utils');

module.exports = (options, callback) => {
    let op = '-a logs/wget.log';
    if (options.name) {
        if (options.path) {
            exec(`mkdir -p "downloads/${options.path}"`);
            op += ` -O "downloads/${options.path}/${options.name}"`;
        } else {
            op += ` -O "downloads/${options.name}"`;
        }
    } else if (options.path) {
        op += ` -P "downloads/${options.path}/"`;
    }

    download(`wget ${op} ${options.url} >> logs/wget.log`, callback);
}

const { exec } = require('child_process');
const config = require('../config');
const { download } = require('./utils');

module.exports = (options, callback) => {
    let op = `-k ${options.playlist !== '0' ? '--playlist' : ''}`;
    if (options.proxy) {
        op += ` -x ${options.proxy}`;
    }
    if (options.name) {
        op += ` -O ${options.name}`;
    }
    if (options.path) {
        exec(`mkdir -p downloads/${options.path}`);
        op += ` -o downloads/${options.path}`;
    }
    else {
        op += ` -o downloads`;
    }
    if (options.url.indexOf("bilibili") !== -1 && config.bilibili_cookie_path) {
        op += ` -c ${config.bilibili_cookie_path}`;
    }

    download(`you-get ${op} '${options.url}' >> logs/you-get.log`, callback);
}

const { download } = require('./utils');

module.exports = (options, callback) => {
    let op = ``;
    let path = '';
    if (options.path) {
        path = `downloads/${options.path}/%(title)s.%(ext)s`;
    }
    else {
        path = `downloads/%(title)s.%(ext)s`;
    }
    op += ` -o '${path}'`;

    download(`yt-dlp ${op} '${options.url}' >> logs/youtube-dl.log`, callback);
}

const { exec } = require('child_process');
const config = require('../config');

const download = (command, callback) => {
    let retryTimes = config.retryTimes;
    if (config.command_prefix) {
        command = `${config.command_prefix} && ` + command;
    }
    const dl = () => {
        exec(command, (err, stdout, stderr) => {
            if (err) {
                if (retryTimes > 0) {
                    retryTimes--;
                    dl();
                } else {
                    callback(1, stderr);
                }
            } else {
                callback();
            }
        });
    }
    dl();
}

module.exports = {
    download,
}
